"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/metric.css";
import { ArrowDownRight, ArrowUpRight, Minus } from "@phosphor-icons/react";
import type { HTMLAttributes, ReactNode } from "react";
import { cn } from "../../lib/cn";

export type MetricTrend = {
  label: string;
  value?: ReactNode;
  direction?: "up" | "down" | "flat";
  sentiment?: "positive" | "negative" | "neutral";
};

export type MetricProps = HTMLAttributes<HTMLDivElement> & {
  label: string;
  value: ReactNode;
  trend?: MetricTrend;
  context?: ReactNode;
  visual?: ReactNode;
  loading?: boolean;
};

export function Metric({ label, value, trend, context, visual, loading = false, className, ...props }: MetricProps) {
  const TrendIcon = trend?.direction === "up" ? ArrowUpRight : trend?.direction === "down" ? ArrowDownRight : Minus;
  return (
    <div className={cn("whatiuse-metric", className)} role="group" aria-label={label} aria-busy={loading || undefined} {...props}>
      <div className="whatiuse-metric__body">
        <span className="whatiuse-metric__label">{label}</span>
        <strong className="whatiuse-metric__value">{loading ? <span className="whatiuse-metric__placeholder" aria-hidden="true" /> : value}</strong>
        {(trend || context) && <div className="whatiuse-metric__meta">
          {trend && <span className="whatiuse-metric__trend" data-direction={trend.direction ?? "flat"} data-sentiment={trend.sentiment ?? "neutral"}>
            <TrendIcon aria-hidden="true" />
            {trend.value && <strong>{trend.value}</strong>}
            <span>{trend.label}</span>
          </span>}
          {context && <span className="whatiuse-metric__context">{context}</span>}
        </div>}
      </div>
      {visual && <div className="whatiuse-metric__visual" aria-hidden="true">{visual}</div>}
      {loading && <span className="whatiuse-sr-only">Loading {label}</span>}
    </div>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-metric {
  display: flex;
  min-width: 0;
  min-height: 110px;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 15px;
  border-radius: var(--whatiuse-radius-container);
  background: var(--whatiuse-bg-surface);
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--whatiuse-control-border) 58%, transparent), 0 1px 2px rgb(17 17 19 / .025);
}

.whatiuse-metric__body { display: grid; min-width: 0; gap: 5px; }

.whatiuse-metric__label { overflow: hidden; color: var(--whatiuse-fg-muted); font-size: var(--whatiuse-type-label); font-weight: 540; text-overflow: ellipsis; white-space: nowrap; }

.whatiuse-metric__value {
  min-width: 64px;
  color: var(--whatiuse-fg-default);
  font-size: clamp(24px, 3vw, 32px);
  font-variant-numeric: tabular-nums;
  font-weight: 610;
  letter-spacing: -.035em;
  line-height: 1.05;
}

.whatiuse-metric__meta { display: flex; min-width: 0; flex-wrap: wrap; align-items: center; gap: 5px 9px; color: var(--whatiuse-fg-subtle); font-size: var(--whatiuse-type-metadata); }

.whatiuse-metric__trend { display: inline-flex; min-width: 0; align-items: center; gap: 3px; white-space: nowrap; }

.whatiuse-metric__trend svg { width: 12px; height: 12px; }

.whatiuse-metric__trend strong { color: var(--whatiuse-fg-default); font-variant-numeric: tabular-nums; font-weight: 570; }

.whatiuse-metric__trend[data-sentiment="negative"] { color: var(--whatiuse-fg-danger); }

.whatiuse-metric__trend[data-sentiment="negative"] strong { color: inherit; }

.whatiuse-metric__visual {
  display: grid;
  width: min(84px, 30%);
  min-width: 64px;
  min-height: 36px;
  flex: 0 0 auto;
  align-items: end;
}

.whatiuse-metric__visual .whatiuse-sparkline { width: 100%; max-width: 100%; }

.whatiuse-metric__placeholder {
  display: inline-block;
  width: 84px;
  height: .78em;
  border-radius: 5px;
  background: var(--whatiuse-bg-subtle);
  animation: whatiuse-analytics-pulse 1.35s var(--whatiuse-ease) infinite alternate;
}

@media (max-width: 640px) {
.whatiuse-metric { min-height: 92px; gap: 12px; }

.whatiuse-metric__value { font-size: 25px; }
}

@media (prefers-reduced-motion: reduce) {
.whatiuse-metric__placeholder { animation: none; }
}

.whatiuse-metric {
    min-height: 124px;
    padding: 16px;
    border-radius: var(--whatiuse-radius-container);
    background: var(--whatiuse-bg-surface);
    box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--whatiuse-control-border) 58%, transparent), 0 1px 2px rgb(17 17 19 / .025);
  }

.whatiuse-metric__body { gap: 4px; }

.whatiuse-metric__label { font-weight: 500; }

.whatiuse-metric__value { font-size: clamp(26px, 3vw, 32px); font-weight: 620; }

.whatiuse-metric__visual { width: min(112px, 34%); }

@keyframes whatiuse-analytics-pulse { from { opacity: .5; } to { opacity: 1; } }
}
